class Solution { fun minimumTime(n:Int,edges:Array<IntArray>,disappear:IntArray):IntArray{val graph=Array(n){mutableListOf<IntArray>()};for(edge in edges){graph[edge[0]].add(intArrayOf(edge[1],edge[2]));graph[edge[1]].add(intArrayOf(edge[0],edge[2]))};val distance=LongArray(n){Long.MAX_VALUE};distance[0]=0;val queue=java.util.PriorityQueue<LongArray>(compareBy<LongArray>{it[0]});queue.add(longArrayOf(0,0));while(queue.isNotEmpty()){val state=queue.poll();val time=state[0];val node=state[1].toInt();if(time!=distance[node])continue;for(edge in graph[node]){val next=edge[0];val candidate=time+edge[1];if(candidate<distance[next]&&candidate<disappear[next]){distance[next]=candidate;queue.add(longArrayOf(candidate,next.toLong()))}}};return IntArray(n){if(distance[it]==Long.MAX_VALUE)-1 else distance[it].toInt()}} }
